insert into flashcards (tema, pergunta, resposta) values
  ('Cardio-oncologia', 'QUAL A DEFINIÇÃO DE DISFUNÇÃO VENTRICULAR RELACIONADA AO USO DE QUIMIOTERÁPICOS?', 'REDUÇÃO DA FEVE MAIOR OU IGUAL A 10% DA BASAL, PARA UM VALOR ABAIXO DA NORMALDIADE (FEVE <50%).'),
  ('Cardio-oncologia', 'QUAL O PRINCIPAL GRUPO DE MEDICAMENTOS USADOS PARA TRATAMENTO ONCOLÓGICO QUE SÃO CARDIOTÓXICOS?', 'ANTRACICLINAS'),
  ('Cardio-oncologia', 'QUAIS FAIXAM ETÁRIAS COM MAIOR RISCO DE DESENVOLVER DISFUNÇÃO VENTRICULAR RELACIONADA AOS QUIMIOTERÁPICOS?', 'MENORES DE 18 ANOS E MAIORES DE 65 ANOS.'),
  ('Cardio-oncologia', 'QUAL GÊNERO COM MAIOR RISCO DE DESENVOLVER DISFUNÇÃO VENTRICULAR RELACIONADA AOS QUIMIOTERÁPICOS?', 'FEMININO'),
  ('Cardio-oncologia', 'QUAL A INDICAÇÃO DE DOSAGEM DE BNP E TROPONINA NA CARDIOTOXICIDADE POR QUIMIOTERÁPICOS?', 'PACIENTE COM ECO BASAL COM FEVE <55% (LIMÍTROFE OU REDUZIDA), ESSES MARCADORES DEVEM SER DOSADOS EM ATE 72H DO USO DO QUIMIOTERÁPICO, SUGERINDO LESÃO MIOCARDICA PRECOCE MAS AINDA NAO INDICANDO A SUSPENSÃO DA DROGA.'),
  ('Cardio-oncologia', 'COM QUE FREQUÊNCIA O ECOCARDIOGRAMA É PEDIDO PARA PACIENTES EM USO DE QUIMIOTERÁPICO?', 'O ECO EM GERAL É PEDIDO EM 3-6-12 MESES DO INÍCIO DO TRATAMENTO.'),
  ('Cardio-oncologia', 'QUAL O VALOR DE REDUÇÃO DO STRAIN PREDIZ DISFUNÇÃO VENTRICULAR PRECOCE EM CONTEXTO DE USO DE QUIMIOTERÁPICO?', 'UMA REDUÇÃO DO VALOR DO STRAIN EM 15% OU MAIS DO STRAIN BASAL DO PACIENTE. MAS AINDA NAO INDICANDO A SUSPENSÃO DA DROGA.'),
  ('Cardio-oncologia', 'QUAL A PRINCIPAL MEDIDA DE CONTROLE EM PACIENTES COM RISCO ALTO PARA EVOLUIR COM DISFUNÇÃO VENTRICULAR RELACIONADA AOS QUIMIOTERÁPICOS?', 'LIMITAR A DOSE CUMULATIVA DOS QUIMIOTERÁPICOS.'),
  ('Cardio-oncologia', 'QUAL A INDICAÇÃO DA SUSPENSÃO DA TERAPIA ONCOLÓGICA NO PACIENTE QUE DESENVOLVE IC RELACIONADA AO USO DA DROGA?', 'NOS QUE DESENVOLVEM FEVE <40% (ANTRACICLINAS E ANTI-HER2) OU 40-50% COM QUEDA MAIOR QUE 15% (ANTI-HER2)'),
  ('Cardio-oncologia', 'PACIENTES COM FEVE <50% PODEM USAR ANTRACICLINAS?', 'PODEM, CONTUDO DEVEM ESTAR USANDO IECA/BRA E BBLOQ ANTES. PACIENTES COM FEVE <40% NÃO DEVEM USAR A CLASSE A NÃO SER EM ULTIMO CASO.'),
  ('Cardio-oncologia', 'QUANDO INICIAR TRATAMENTO MEDICAMENTOSO PARA IC INDUZIDA PELA QUIMIOTERAPIA?', 'O TRATAMENTO PARA IC DEVE SER INICIADO SEMPRE QUE FEVE <50%'),
  ('Cardio-oncologia', 'QUAL A DROGA QUE PROTEGE O CORAÇÃO DA CARDIOTOXICIDADE DAS ANTRACICLINAS?', 'DEXRAZOXANO'),
  ('Cardio-oncologia', 'COMO O DEXRAZOXANO PROTEGE O CORAÇÃO DA CARDIOTOXICIDADE DAS ANTRACICLINAS?', 'ATUA COMO QUELANTE DE FERRO PREVENINDO A FORMAÇÃO DE RADICAIS LIVRES PELAS ANTRACICLINAS. DEVE SER CONSIDERADO EM PACIENTE ALTO RISCO SUBMETIDO A ALTAS DOSES (>250MG/M2).'),
  ('Cardio-oncologia', 'QUAL A PRINCIPAL CARACTERISTICA DE CARDIOTOXICIDADE TIPO 1?', 'IRREVERSÍVEL'),
  ('Cardio-oncologia', 'ALEM DA IC, O QUE OS INIBIDORES DE TIROSINA QUINASE, AS ANTRACICLINAS, INIBIDORES DE mTOR E RADIOTERAPIA PODEM CAUSAR AO CORAÇÃO?', 'ITQ: HAS, PROLONGAMENTO QT E TROMBOEMBOLISMO
insert into flashcards (tema, pergunta, resposta) values
  ('Aortopatias', 'QUAL O PERFIL DO PACIENTE COM ANEURISMA DE AORTA ASCENDENTE?', 'HAS E DOENÇAS DO COLÁGENO'),
  ('Aortopatias', 'QUAL O PERFIL DO PACIENTE COM ANEURISMA DE AORTA ABDOMINAL?', 'HOMEM TABAGISTA COM >60 ANOS'),
  ('Aortopatias', 'QUAIS AS CARACTERÍSTICAS DO ANEURISMA DE AORTA ABDOMINAL?', 'FUSIFORME E 80% INFRARRENAL'),
  ('Aortopatias', 'QUAL A ETIOPATOGENIA DO ANEURISMA DE AORTA ABDOMINAL?', 'DOENÇA ATEROSCLERÓTICA'),
  ('Aortopatias', 'QUAL A ETIOPATOGENIA DO ANEURISMA DE AORTA ASCENDENTE?', 'A DEGENERAÇÃO CÍSTICA DA CAMADA MÉDIA'),
  ('Aortopatias', 'QUANDO INDICAR INTERVENÇÃO EM UM ANEURISMA DE AORTA COM DIÂMETRO >55 MM?', 'TODOS'),
  ('Aortopatias', 'QUANDO INDICAR INTERVENÇÃO EM UM ANEURISMA DE AORTA COM DIÂMETRO MAIOR QUE 50 MM?', 'MARFAN OU BICUSPIDE COM FATORES DE RISCO'),
  ('Aortopatias', 'QUANDO INDICAR INTERVENÇÃO NO ANEURISMA DE AORTA EM PACIENTE COM VÁLVULA AÓRTICA BICÚSPIDE?', 'SE >55MM OU SE >50MM COM FATORES DE RISMO (HISTÓRIA FAMILIAR DE DISSECÇÃO, CRESCIMENTO >3MM AO ANO, IAo IMPORTANTE, COARCTAÇÃO, HAS)'),
  ('Aortopatias', 'QUANDO INDICAR INTERVENÇÃO NO ANEURISMA DE AORTA EM PACIENTE COM MARFAN?', 'SE >50MM OU SE >45MM COM FATORES DE RISMO (HISTÓRIA FAMILIAR DE DISSECÇÃO, CRESCIMENTO >3MM AO ANO, IAo IMPORTANTE, DESEJO DE ENGRAVIDAR)'),
  ('Aortopatias', 'QUANDO INDICAR INTERVENÇÃO NO ANEURISMA DE AORTA EM PACIENTE QUE JÁ SERÁ SUBMETIDO A CIRURGIA CARDÍACA?', 'SE >45MM'),
  ('Aortopatias', 'QUAIS AS PRINCIPAIS COMPLICAÇÕES DE ANEURISMA DE AORTA ABDOMINAL?', 'TROMBOEMBOLISMO DISTAL, EXPANSÃO RÁPIDA E RUPTURA'),
  ('Aortopatias', 'O QUE É DISSECÇÃO DE AORTA STANFORD A E B?', 'STANFORD A: ACOMETE A AORTA ASCENDENTE (COM OU SEM EXTENSÃO AO ARCO/DESCENDENTE). STANFORD B: ACOMETE APENAS A AORTA DESCENDENTE (DISTAL À SUBCLÁVIA ESQUERDA), SEM ENVOLVER A ASCENDENTE'),
  ('Aortopatias', 'QUAL O TRATAMETO INICIAL DA DISSECÇÃO DE AORTA NA EMERGÊNCIA?', '1- BETABLOQ / 2-VASODILATADOR EV / 3-MORFINA'),
  ('Aortopatias', 'QUAL O TRATAMENTO DA DISSECÇÃO DE AORTA STANFORD A?', 'CIRURGIA'),
  ('Aortopatias', 'QUAL O TRATAMENTO DA DISSECÇÃO DE AORTA STANFORD B NÃO COMPLICADA?', 'CLÍNICO (BETABLOQ, VASODILATADOR E ANALGESIA)'),
  ('Aortopatias', 'QUANDO PENSAR EM DISSECÇÃO DE AORTA STANFORD B COMPLICADA?', 'DOR REFRATÁRIA, ISQUEMIA DE ÓRGÃOS, SINAIS DE RUPTURA IMINENTE OU JA ROTA, DILATAÇÃO ANEURISMÁTICA IMPORTANTE OU PROGRESSIVA');
insert into flashcards (tema, pergunta, resposta) values
  ('Respirações', 'A RESPIRAÇÃO DE CHEYNE STOKES ESTÁ RELACIONADA COM QUAIS DOENÇAS?', 'IC,'),
  ('Respirações', 'NA APNEIA CENTRAL, A VNI É INDICADA?', 'NÃO, AUMENTA'),
  ('Respirações', 'NA APNEIA OBSTRUTIVA DO SONO, A VNI É INDICADA?', 'SIM, PODE AUMENTAR A QUALIDADE DO SONO');
insert into flashcards (tema, pergunta, resposta) values
  ('Insuficiência Cardíaca', 'QUAIS AS FASES DA DIÁSTOLE EM ORDEM?', 'RELAXAMENTO ISOVOLUMÉTRICO, ENCHIMENTO RÁPIDO, DIÁSTASE, CONTRAÇÃO ATRIAL'),
  ('Insuficiência Cardíaca', 'EM QUAL FASE DA DIÁSTOLE OCORRE A MAIOR PARTE DO ENCHIMENTO VENTRICULAR?', 'ENCHIMENTO RÁPIDO (INÍCIO)'),
  ('Insuficiência Cardíaca', 'DURANTE O RELAXAMENTO ISOVOLUMÉTRICO COMO ESTÃO AS VÁLVULAS ATRIOVENTRICULARE AS SEMILUNARES?', 'FECHADAS E FECHADAS'),
  ('Insuficiência Cardíaca', 'O QUE OCORRE COM PRESSÃO E VOLUME DURANTE O RELAXAMENTO ISOVOLUMÉTRICO?', 'REDUÇÃO DE PRESSÃO, SEM REDUÇÃO DE VOLUME'),
  ('Insuficiência Cardíaca', 'EM QUE PERÍODO OCORRE O RELAXAMENTO ISOVOLUMÉTRICO?', 'ENTRE O FECHAMENTO DAS VÁLVULAS SEMILUNARES E A ABERTURA DAS ATRIOVENTRICULARES'),
  ('Insuficiência Cardíaca', 'O RELAXAMENTO VENTRICULAR DEPENDE DE ENERGIA (GASTO DE ATP)?', 'SIM, PARA PUXAR O CÁLCIO DE VOLTA AO RETÍCULO SARCOPLASMÁTICO'),
  ('Insuficiência Cardíaca', 'DURANTE A CONTRAÇÃO ISOVOLUMÉTRICA COMO ESTÃO AS VÁLVULAS ATRIOVENTRICULARE AS SEMILUNARES?', 'FECHADAS E FECHADAS'),
  ('Insuficiência Cardíaca', 'O QUE OCORRE COM PRESSÃO E VOLUME DURANTE A CONTRAÇÃO ISOVOLUMÉTRICA?', 'AUMENTO DE PRESSÃO, SEM REDUÇÃO DE VOLUME'),
  ('Insuficiência Cardíaca', 'FRANK-STARLING REPRESENTA PRÉ OU PÓS-CARGA?', 'PRÉ-CARGA (ESTRESSE PARIETAL NO FINAL DA DIÁSTOLE)'),
  ('Insuficiência Cardíaca', 'QUANTO MAIOR A PRÉ-CARGA MAIOR O VOLUME SISTÓLICO?', 'NÃO, PELA LEI DE FRANK-STARLING, APENAS ATÉ DETERMINADO PONTO O ESTIRAMENTO AUMENTA O VOLUME SISTÓLICO'),
  ('Insuficiência Cardíaca', 'QUAIS OS TRÊS PARÂMETROS QUE INFLUENCIAM NO INOTROPISMO?', 'CONTRATILIDADE, FREQUÊNCIA CARDÍACA E PRÉ-CARGA (FRANK STARLING)'),
  ('Insuficiência Cardíaca', 'O ESTRESSE PARIETAL NA PAREDE DO VENTRICULO É MAIOR QUANTO MAIOR…', 'O TAMANHO E A ESPESSURA DO VENTRICULO'),
  ('Insuficiência Cardíaca', 'QUAL O EFEITO DA ESTIMULAÇÃO PARASSIMPÁTICA NO CORAÇÃO?', 'REDUÇÃO DE FREQUÊNCIA E INOTROPISMO'),
  ('Insuficiência Cardíaca', 'A INIBIÇÃO BETA-ADRENÉRGICA FAZ O QUE COM A AMPc E COM O CÁLCIO INTRACELULAR?', 'REDUZ'),
  ('Insuficiência Cardíaca', 'QUAL O EFEITO DA ESTIMULAÇÃO SIMPÁTICA NO CORAÇÃO?', 'AUMENTO DE FREQUÊNCIA E INOTROPISMO'),
  ('Insuficiência Cardíaca', 'A ESTIMULAÇÃO BETA-ADRENÉRGICA FAZ O QUE COM A AMPc E COM O CÁLCIO INTRACELULAR?', 'AUMENTA'),
  ('Insuficiência Cardíaca', 'QUAL NOME DAS BOMBAS DE CÁLCIO QUE LEVAM O CÁLCIO AO RETÍCULO ENDOPASMÁTICO?', 'SERCA-2 (PROCESSO ATIVO, TEM GASTO DE ATP)'),
  ('Insuficiência Cardíaca', 'QUAL PROTEÍNA REGULA AS BOMBAS DE CÁLCIO?', 'FOSFOLAMBAM'),
  ('Insuficiência Cardíaca', 'O CÁLCIO SE LIGA A QUAL PROTÉINA NA SARCOMÊRO?', 'TROPONINA C (“C DE CÁLCIO OU DE COMEÇO”)'),
  ('Insuficiência Cardíaca', 'A TROPONINA C ATIVA A TROPONINA I FAZENDO ALTERAR A CONFORMAÇÃO DA TROPOMIOSINA PARA QUE?', 'PARA LIBERAR A CABEÇA DE MIOSINA PARA CONTRAÇÃO'),
  ('Insuficiência Cardíaca', 'QUAIS AS DUAS PROTÉNAS PRINCIPAIS DO SARCÔMERO (UNIDADE FUNCIONAL CARDÍACA)?', 'ACTINA (FILAMENTO FINO) E MIOSINA (FILAMENTO ESPESSO)'),
  ('Insuficiência Cardíaca', 'O QUE É A TITINA?', 'PROTEÍNA LONGA, FINA E FLEXÍVEL, INFLUENCIA DE MANEIRA IMPORTANTE NAS PROPRIEDADES ELÁSTICAS DIÁSTÓLICAS DO CORAÇÃO (ICFEP)'),
  ('Insuficiência Cardíaca', 'A TITINA LIGA A MIOSINA A QUAL LINHA?', 'LINHA Z (LIMITE DO SARCÔMERO) POR UM SEGMENTO INEXTENSÍVEL ATÉ POUCO ANTES DA LINHA M POR UM SEGMENTO EXTENSÍVEL'),
  ('Insuficiência Cardíaca', 'COMO É A ESCALA DE SINTOMAS DE NYHA?', 'NYHA 1 AUSÊNCIA DE SINTOMAS
