insert into flashcards (tema, pergunta, resposta) values
  ('Pulsos', 'EM QUE SITUAÇÃO A DIFERENÇA DA PRESSÃO SISTÓLICA DA INSPIRAÇÃO E DA EXPIRAÇÃO É >10MMHG?', 'PULSO PARADOXAL'),
  ('Pulsos', 'QUAL SITUAÇÃO OCORRE PULSO PARADOXAL?', 'TAMPONAMENTO CARDÍACO, PERICARDITE CONTRICTIVA, PNEUMOTÓRAX, ASMA, EMBOLIA PULMONAR, GESTAÇÃO, OBESIDADE, HIPOVOLEMIA'),
  ('Pulsos', 'PODE OCORRER TAMPONAMENTO SEM PULSO PARADOXAL COM QUAIS SITUAÇÕES ASSOCIADAS?', 'CIA, IC IMPORTANTE, TAMPONAMENTO COM COAGULO E IAo IMPORTANTE'),
  ('Pulsos', 'SITUAÇÕES QUE TAMPONAMENTO NÃO GERA PULSO PARADOXAL?', 'CIA, DERRAME PERICARDICO COAGULADO, DISFUNÇÃO VE IMPORTANTE, IAo IMPORTANTE'),
  ('Pulsos', 'QUAL O NOME DO PULSO ARTERIAL NA INSUFICIÊNCIA AÓRTICA?', 'MARTELO D´ÁGUA (NÃO É PATOGNOMÔNICO E NEM OBRIGATÓRIO)'),
  ('Pulsos', 'COMO ACENTUAR O PULSO MARTELO D´ÁGUA NA INSUFICIÊNCIA AÓRTICA?', 'LEVANTANDO O BRAÇO'),
  ('Pulsos', 'QUAL O NOME DO PULSO ARTERIAL NA ESTENOSE AÓRTICA?', 'PARVUS TARDUS'),
  ('Pulsos', 'QUAL O NOME DO PULSO ARTERIAL COM DOIS PICOS PROEMINENTES NA SÍSTOLE? ONDE OCORRE?', 'BISFERIENS. NA DUPLA LESÃO AÓRTICA E NA HIPERTRÓFICA'),
  ('Pulsos', 'QUAL O NOME DO PULSO ARTERIAL COM UM PICO PROEMINENTES NA SÍSTOLE E UM NA DIÁSTOLE? ONDE OCORRE?', 'DICRÓTICO. EM SITUAÇÕES DE GRAVIDADE: BALÃO INTRA-AÓRTICO, HIPOVOLEMIA, DERRAME PERICÁRDICO OU ARRITMIA'),
  ('Pulsos', 'NO PULSO VENOSO O QUE REPRESENTA A ONDA A, ONDA C, ONDA X, ONDA V E DESCENSO Y?', 'ONDA A: CONTRAÇÃO DO ÁTRIO
insert into flashcards (tema, pergunta, resposta) values
  ('Ausculta', 'QUAIS SONS SÃO MAIS BEM AUSCULTADOS COM A CAMPÂNULA DO ESTETO?', 'B3, B4 E RUFLARES MITRAL E TRICÚSPIDE'),
  ('Ausculta', 'QUAIS FATORES FAZEM A B1 HIPERFONÉTICA?', 'CORAÇÃO HIPERDINÂMICO, INTERVALO PR CURTO E ESTENOSE MITRAL COM CÚSPIDES DELGADAS'),
  ('Ausculta', 'QUAIS FATORES FAZEM A B1 HIPOFONÉTICA?', 'ICFER, INTERVALO PR LONGO E ESTENOSE MITRAL COM CÚSPIDES CALCIFICADAS E INSUFICIÊNCIA MITRAL (EXCETO PROLAPSO)'),
  ('Ausculta', 'QUAIS FATORES FAZEM A B2 HIPERFONÉTICA?', 'HAS, HP, COARCTAÇÃO AORTA, ANEURISMA AORTA ASCENDENTE, FALLOT, TGA'),
  ('Ausculta', 'QUAIS FATORES FAZEM A B2 HIPOFONÉTICA?', 'INSUFICIÊNCIA AÓRTICA, ESTENOSE AÓRTICA, ESTENOSE PULMONAR'),
  ('Ausculta', 'NORMALMENTE NA SEGUNDA BULHA A P2 VEM ANTES, JUNTO OU DEPOIS DA A2?', 'DEPOIS'),
  ('Ausculta', 'NO DESDOBRAMENTO FISIOLÓGICO, A P2 APROXIMA OU AFASTA DA A2 AO INSPIRAR?', 'AFASTA, DEVIDO AO RETORNO AUMENTADO EM CÂMARAS DIREITAS'),
  ('Ausculta', 'O QUE É O DESDOBRAMENTO AMPLO DE B2?', 'AGRAVEMENTO DO DESDOBRAMENTO'),
  ('Ausculta', 'QUAIS SITUAÇÕES GERAM DESDOBRAMENTO AMPLO DE B2?', 'BRD, DOENÇAS DO VENTRÍCULO DIREITO, IM'),
  ('Ausculta', 'O QUE É O DESDOBRAMENTO PARADOXAL DE B2?', 'P2 VEM ANTES DE A2, AI NA INSPIRAÇÃO MELHORA O DESDOBRAMENTO'),
  ('Ausculta', 'QUAIS SITUAÇÕES GERAM DESDOBRAMENTO PARADOXAL DE B2?', 'BRE, ESTENOSE E INSUFICIÊNCIA AÓRTICA, HAS, PERSISTÊNCIA CANAL ARTERIAL. MAS PODE ESTAR PRESENTE EM SITUAÇÕES FISIOLÓGICAS, COMO A GESTAÇÃO.'),
  ('Ausculta', 'O QUE É O DESDOBRAMENTO FIXO DE B2?', 'INSPIRAÇÃO E EXPIRAÇÃO NÃO ALTERAM A B2'),
  ('Ausculta', 'QUAIS SITUAÇÕES GERAM DESDOBRAMENTO FIXO DE B2?', 'CIA'),
  ('Ausculta', 'O QUE SIGNIFICA A B3 E ELA OCORRE EM QUE MOMENTO DO CICLO CARDÍACO?', 'SOBRECARGA DE VOLUME, PROTODIASTÓLICO NO RELAXAMENTO VENTRICULAR (MAIS AUDÍVEL EM DECÚBITO LATERAL ESQUERDO)'),
  ('Ausculta', 'QUAIS AS CAUSAS DE SONS PROTODIASTÓLICOS?', 'B3
insert into flashcards (tema, pergunta, resposta) values
  ('Miocárdio', 'QUAIS OS FENÓTIPOS PRINCIPAIS DAS MIOCARDIOPATIAS?', 'DILATADAS, HIPERTRÓFICAS, RESTRITIVAS, ARRITMOGÊNICAS'),
  ('Miocárdio', 'QUAIS AS CAUSAS DE MIOCARDIOPATIA DILATADA?', 'CHAGAS, ALCOÓLICA, TÓXICAS (QUIMIOTERAPIA), PERIPARTO, INFECCIOSAS, AUTOIMUNE (HIPOTIREOIDISMO, LÚPUS), NUTRICIONAIS, GENÉTICAS'),
  ('Miocárdio', 'A HEMOCROMATOSE HEREDITÁRIA POSSUI ORIGEM RECESSIVA OU DOMINANTE?', 'RECESSIVA'),
  ('Miocárdio', 'QUAIS OS SINTOMAS DE HEMOCROMATOSE?', 'INSUFICIÊNCIA CARDÍACA RESTRITIVA, ALTERAÇÃO CUTÂNEA (BRONZE), HIPOGONADISMO, DIABETES, CIRROSE'),
  ('Miocárdio', 'QUANDO SUSPEITAR DE HEMOCROMATOSE?', 'SINTOMAS, SATURAÇÃO DE TRANSFERRINA >45% E FERRITINA >500'),
  ('Miocárdio', 'QUAL O ACHADO DA RNM CARDÍACA NA HEMOCROMATOSE?', 'MAPA T2 ESTRELA REDUZIDO'),
  ('Miocárdio', 'QUAL O TRATAMENTO DA HEMOCROMATOSE?', 'SANGRIA E QUELANTES DE FERRO
insert into flashcards (tema, pergunta, resposta) values
  ('Válvula', 'CRITÉRIOS DE ESTENOSE AÓRTICA GRAVE (ALTO GRADIENTE)?', 'ÁREA <1,0CM², GRADIENTE MÉDIO ≥40MMHG, VELOCIDADE ≥4M/S.'),
  ('Válvula', 'ÁREA 1,3CM² E GRADIENTE 34MMHG: QUE GRAU DE ESTENOSE AÓRTICA?', 'MODERADA.'),
  ('Válvula', 'FATORES COMPLICADORES DA ESTENOSE AÓRTICA?', 'FE<50%, VELOCIDADE>5M/S, GRADIENTE>60MMHG, AVA<0,7CM², HIPOTENSÃO AO ESFORÇO.'),
  ('Válvula', 'NA ESTENOSE AÓRTICA, O QUE É O PADRÃO "BAIXO FLUXO/BAIXO GRADIENTE COM FE REDUZIDA" (D2)?', 'ÁREA<1CM², GRADIENTE<40MMHG, FE REDUZIDA — DÚVIDA ENTRE ESTENOSE VERDADEIRA E PSEUDOESTENOSE.'),
  ('Válvula', 'NO PADRÃO D2 (ESTENOSE AÓRTICA), QUAL EXAME DIFERENCIA ESTENOSE VERDADEIRA DE PSEUDOESTENOSE?', 'ECO DE ESTRESSE COM BAIXA DOSE DE DOBUTAMINA.'),
  ('Válvula', 'O QUE CONFIRMA ESTENOSE VERDADEIRAMENTE GRAVE NO ECO COM DOBUTAMINA?', 'ÁREA PERMANECE PEQUENA MESMO COM MAIS FLUXO; GRADIENTE SOBE ≥40MMHG.'),
  ('Válvula', 'O QUE É RESERVA CONTRÁTIL E SEU LIMIAR?', 'AUMENTO ≥20% DO VOLUME EJETADO COM DOBUTAMINA.'),
  ('Válvula', 'NA ESTENOSE AÓRTICA, O QUE É O PADRÃO "PARADOXAL" (D3)?', 'FE PRESERVADA, VE PEQUENO/HIPERTROFIADO, BAIXO VOLUME EJETADO INDEXADO (<35ML/M²).'),
  ('Válvula', 'NA ESTENOSE AÓRTICA, QUAL EXAME CONFIRMA GRAVIDADE NO PADRÃO PARADOXAL (FE PRESERVADA)?', 'ESCORE DE CÁLCIO POR TOMOGRAFIA.'),
  ('Válvula', 'VALOR DE ESCORE DE CÁLCIO QUE REFORÇA ESTENOSE AÓRTICA GRAVE?', 'EM TORNO DE >1650UA.'),
  ('Válvula', 'O TESTE ERGOMÉTRICO É SEGURO EM ESTENOSE AÓRTICA GRAVE SINTOMÁTICA?', 'NÃO, CONTRAINDICADO; SÓ EM ASSINTOMÁTICOS.'),
  ('Válvula', 'QUANDO PREFERIR CIRURGIA CONVENCIONAL SOBRE TAVI?', 'BAIXO RISCO CIRÚRGICO (STS<4%), PACIENTES JOVENS.'),
  ('Válvula', 'QUANDO O TAVI É PREFERIDO?', 'RISCO ALTO/PROIBITIVO (STS>8%) OU IDOSOS, MESMO EM BAIXO RISCO (>70 ANOS).'),
  ('Válvula', 'A VALVULOPLASTIA AÓRTICA POR BALÃO É TRATAMENTO DEFINITIVO?', 'NÃO, SÓ PONTE TERAPÊUTICA.'),
