  ('Taquiarritmia', 'APÓS ABLAÇÃO DO NÓ AV COM MP EM VVI, QUE COMPLICAÇÃO GRAVE PODE OCORRER?', 'TORSADES DE POINTES POR BRADICARDIA/QT LONGO.'),
  ('Taquiarritmia', 'O QUE É O BLOQUEIO DE RAMO ALTERNANTE E SUA CONDUTA?', 'ALTERNÂNCIA BRD/BRE, DOENÇA INFRA-HISSIANA GRAVE — MARCA-PASSO DEFINITIVO MESMO ASSINTOMÁTICO.'),
  ('Taquiarritmia', 'QUANDO O ESTUDO ELETROFISIOLÓGICO DIAGNÓSTICO É INDICADO?', 'SÍNCOPE INEXPLICADA COM SUSPEITA DE ARRITMIA COMPLEXA, SEM INDICAÇÃO FORMAL JÁ ESTABELECIDA DE CDI/MP.'),
  ('Taquiarritmia', 'A FA PÓS-OPERATÓRIA É MAIS COMUM EM TROCA VALVAR OU REVASCULARIZAÇÃO?', 'TROCA VALVAR.'),
  ('Taquiarritmia', 'O BETABLOQUEADOR PRÉ-OPERATÓRIO PREVINE FA PÓS-OP?', 'SIM.'),
  ('Taquiarritmia', 'FA PÓS-OP ESTÁVEL: CARDIOVERSÃO IMEDIATA É MANDATÓRIA?', 'NÃO, PRIORIZAR CONTROLE DE FREQUÊNCIA.'),
  ('Taquiarritmia', 'FLUTTER EM PACIENTE COM FA PAROXÍSTICA PRÉVIA: TRATAMENTO DEFINITIVO?', 'ABLAÇÃO DO ISTMO CAVOTRICUSPÍDEO.');
insert into flashcards (tema, pergunta, resposta) values
  ('Síncope e Anticoagulação', 'QUAIS OS PILARES DA AVALIAÇÃO INICIAL DA SÍNCOPE?', 'HISTÓRIA CLÍNICA E EXAME FÍSICO, RESPONSÁVEIS PELO DIAGNÓSTICO EM 50-70% DOS CASOS.'),
  ('Síncope e Anticoagulação', 'QUAL EXAME É OBRIGATÓRIO EM TODO PACIENTE COM SÍNCOPE?', 'ECG DE 12 DERIVAÇÕES.'),
  ('Síncope e Anticoagulação', 'QUAL O OBJETIVO INICIAL DA AVALIAÇÃO DA SÍNCOPE?', 'DISTINGUIR SÍNCOPES REFLEXAS (BENIGNAS) DE CAUSAS CARDÍACAS POTENCIALMENTE FATAIS.'),
  ('Síncope e Anticoagulação', 'MORDEDURA DE LÍNGUA LATERAL E INCONTINÊNCIA URINÁRIA SÃO TÍPICAS DE SÍNCOPE OU CRISE CONVULSIVA?', 'CRISE CONVULSIVA (RARAS NA SÍNCOPE).'),
  ('Síncope e Anticoagulação', 'A SÍNCOPE ARRÍTMICA TEM QUE CARACTERÍSTICAS DE INÍCIO/DURAÇÃO?', 'INÍCIO RÁPIDO, DURAÇÃO BREVE, SEM CONFUSÃO PÓS-ICTAL.'),
  ('Síncope e Anticoagulação', 'PALPITAÇÕES PRÉVIAS SÃO COMUNS QUANDO A PERDA DE CONSCIÊNCIA É RÁPIDA?', 'NÃO, GERALMENTE AUSENTES.'),
  ('Síncope e Anticoagulação', 'PODE HAVER CONVULSÃO NA SÍNCOPE?', 'SIM (SÍNCOPE CONVULSIVA), RARA, APÓS ASSISTOLIA PROLONGADA OU TV.'),
  ('Síncope e Anticoagulação', 'QUAL O QUADRO CLÁSSICO DA SÍNCOPE VASOVAGAL?', 'JOVEM, EM PÉ/AMBIENTE QUENTE, PRÓDROMOS DE MAL-ESTAR E NÁUSEAS, SEM PALPITAÇÕES.'),
  ('Síncope e Anticoagulação', 'O DIAGNÓSTICO DE SÍNCOPE VASOVAGAL TÍPICA É CLÍNICO?', 'SIM, PELA ANAMNESE TÍPICA.'),
  ('Síncope e Anticoagulação', 'QUAL O TRATAMENTO INICIAL DA SÍNCOPE VASOVAGAL?', 'EDUCAÇÃO, RECONHECIMENTO DE PRÓDROMOS, INGESTA HÍDRICA/SAL, MANOBRAS DE CONTRAPRESSÃO.'),
  ('Síncope e Anticoagulação', 'BETABLOQUEADORES PREVINEM SÍNCOPE VASOVAGAL?', 'NÃO, SEM SUPERIORIDADE AO PLACEBO (ESTUDO POST).'),
  ('Síncope e Anticoagulação', 'A FLUDROCORTISONA É 1ª LINHA NA SÍNCOPE REFLEXA?', 'NÃO, RESERVADA A CASOS REFRATÁRIOS.'),
  ('Síncope e Anticoagulação', 'QUAL O PAPEL DO TILT TEST?', 'DISTINGUIR SÍNCOPE REFLEXA DE PSEUDOSSÍNCOPE, EM CASOS DE DIAGNÓSTICO INCERTO.'),
  ('Síncope e Anticoagulação', 'O TILT TEST É ROTINA PARA TODA SÍNCOPE?', 'NÃO, SÓ SE DIAGNÓSTICO INCERTO APÓS AVALIAÇÃO INICIAL.'),
  ('Síncope e Anticoagulação', 'O TILT TEST É INDICADO NA SÍNCOPE DE ESFORÇO?', 'NÃO — SUGERE CAUSA ESTRUTURAL/ARRÍTMICA, EXIGE OUTRA INVESTIGAÇÃO.'),
  ('Síncope e Anticoagulação', 'O TILT TEST GUIA A ESCOLHA TERAPÊUTICA?', 'NÃO, É SÓ DIAGNÓSTICO.'),
  ('Síncope e Anticoagulação', 'COMO SE DIAGNOSTICA A HIPERSENSIBILIDADE DO SEIO CAROTÍDEO?', 'MASSAGEM REPRODUZINDO SÍNCOPE COM ASSISTOLIA >3S E/OU QUEDA DE PAS ≥50MMHG.'),
  ('Síncope e Anticoagulação', 'QUANDO INDICAR MARCA-PASSO NA HIPERSENSIBILIDADE DO SEIO CAROTÍDEO?', 'PAUSA SINTOMÁTICA >3S (OU ASSINTOMÁTICA >6S) COM SÍNCOPE RECORRENTE >40 ANOS; MODO BICAMERAL.'),
  ('Síncope e Anticoagulação', 'SÍNCOPE + ECG COM BAV DE ALTO GRAU EM IDOSO: CONDUTA?', 'MARCA-PASSO DEFINITIVO, SEM NECESSIDADE DE TILT TEST/HOLTER.'),
  ('Síncope e Anticoagulação', 'QUAL A CAUSA CARDÍACA MAIS COMUM DE SÍNCOPE?', 'BRADIARRITMIAS (NÓ SINUSAL, BAV), NÃO FIBRILAÇÃO VENTRICULAR.'),
  ('Síncope e Anticoagulação', 'SÍNCOPE EM REPOUSO + SUPRA DE ST EM V1-V2 SEGUIDO DE T NEGATIVA: DIAGNÓSTICO E CONDUTA?', 'SÍNDROME DE BRUGADA TIPO 1; CDI (PREVENÇÃO SECUNDÁRIA).'),
  ('Síncope e Anticoagulação', 'A AMIODARONA PREVINE MORTE SÚBITA NA BRUGADA?', 'NÃO, INEFICAZ E POTENCIALMENTE PROARRÍTMICA.'),
  ('Síncope e Anticoagulação', 'O QUE É A POTS?', 'DISAUTONOMIA COM AUMENTO DA FC ≥30BPM AO ORTOSTATISMO, SEM QUEDA SIGNIFICATIVA DE PA.'),
  ('Síncope e Anticoagulação', 'QUAL EXAME CONFIRMA A POTS?', 'TILT TEST.'),
  ('Síncope e Anticoagulação', 'QUAL O TRATAMENTO NÃO FARMACOLÓGICO PRINCIPAL DA POTS?', 'RECONDICIONAMENTO FÍSICO.'),
  ('Síncope e Anticoagulação', 'QUAL ESCORE ESTRATIFICA RISCO TROMBOEMBÓLICO NA FA?', 'CHA2DS2-VASC.'),
  ('Síncope e Anticoagulação', 'QUAL ESCORE ESTRATIFICA RISCO HEMORRÁGICO?', 'HAS-BLED (≥3 = VIGILÂNCIA, NÃO CONTRAINDICAÇÃO).'),
  ('Síncope e Anticoagulação', 'EM VALVOPATIA SIGNIFICATIVA, O CHA2DS2-VASC DEVE GUIAR A DECISÃO DE ANTICOAGULAR?', 'NÃO — A VALVOPATIA JÁ INDICA ANTICOAGULAÇÃO POR SI SÓ.'),
  ('Síncope e Anticoagulação', 'QUAL O ALVO DE RNI EM PRÓTESE MECÂNICA MITRAL?', '2,5 A 3,5.'),
  ('Síncope e Anticoagulação', 'DOACS PODEM SER USADOS EM PRÓTESE MECÂNICA OU ESTENOSE MITRAL GRAVE?', 'NÃO, VARFARINA É O PADRÃO-OURO.'),
  ('Síncope e Anticoagulação', 'DOACS PODEM SER USADOS EM ESTENOSE AÓRTICA?', 'SIM, SEM CONTRAINDICAÇÃO ABSOLUTA.'),
  ('Síncope e Anticoagulação', 'POR QUANTO TEMPO MANTER ANTICOAGULAÇÃO APÓS CARDIOVERSÃO?', 'PELO MENOS 4 SEMANAS.'),
  ('Síncope e Anticoagulação', 'O FLUTTER TEM RISCO EMBÓLICO MENOR QUE A FA?', 'NÃO, MESMO ALVO DE INR (2,0-3,0).'),
  ('Síncope e Anticoagulação', 'QUAL O MECANISMO DA DABIGATRANA?', 'INIBIDOR DIRETO DA TROMBINA (FATOR IIA).'),
  ('Síncope e Anticoagulação', 'QUAL O MECANISMO DA EDOXABANA/RIVAROXABANA/APIXABANA?', 'INIBIDORES DIRETOS DO FATOR XA.'),
  ('Síncope e Anticoagulação', 'A DABIGATRANA É SEGURA EM IRC GRAVE (CLCR <30)?', 'NÃO, ~80% ELIMINAÇÃO RENAL — CONTRAINDICADA.'),
  ('Síncope e Anticoagulação', 'QUANDO REDUZIR A DOSE DE APIXABANA PARA 2,5MG 12/12H?', '≥2 DE 3: IDADE ≥80, PESO ≤60KG, CREATININA ≥1,5.'),
  ('Síncope e Anticoagulação', 'QUAL ANTICOAGULANTE PREFERIR EM IRC TERMINAL/DIÁLISE?', 'VARFARINA.'),
  ('Síncope e Anticoagulação', 'QUAL O MECANISMO DE AÇÃO DA HBPM?', 'POTENCIALIZA A ANTITROMBINA, COM PREDOMÍNIO SOBRE O FATOR XA.'),
  ('Síncope e Anticoagulação', 'QUANDO DOSAR O FATOR ANTI-XA EM USUÁRIO DE HBPM?', 'INSUFICIÊNCIA RENAL GRAVE E OBESIDADE MÓRBIDA.'),
  ('Síncope e Anticoagulação', 'QUAIS DROGAS POTENCIALIZAM O EFEITO DA VARFARINA?', 'AMIODARONA, CIMETIDINA, FLUCONAZOL, METRONIDAZOL, ERITROMICINA.'),
  ('Síncope e Anticoagulação', 'QUAIS DROGAS REDUZEM O EFEITO DA VARFARINA?', 'BARBITÚRICOS, CARBAMAZEPINA, RIFAMPICINA, FENITOÍNA, COLESTIRAMINA.'),
  ('Síncope e Anticoagulação', 'IECA + DIURÉTICO POUPADOR DE POTÁSSIO: RISCO DE QUÊ?', 'HIPERCALEMIA.'),
  ('Síncope e Anticoagulação', 'ESTATINA + INIBIDOR DE PROTEASE: RISCO DE QUÊ?', 'MIOPATIA/RABDOMIÓLISE.'),
  ('Síncope e Anticoagulação', 'NITRATO + INIBIDOR DE FOSFODIESTERASE-5: POR QUE CONTRAINDICADO?', 'HIPOTENSÃO SEVERA REFRATÁRIA.'),
  ('Síncope e Anticoagulação', 'FA >48H NO PÓS-OP DE CIRURGIA CARDÍACA: ANTICOAGULAR?', 'SIM.'),
  ('Síncope e Anticoagulação', 'ESTRATÉGIA ANTITROMBÓTICA APÓS 30 DIAS DE ICP EM FA?', 'DOAC + CLOPIDOGREL, EVITANDO TRIPLA TERAPIA PROLONGADA.'),
  ('Síncope e Anticoagulação', 'QUANDO A OCLUSÃO DO APÊNDICE ATRIAL ESQUERDO É INDICADA?', 'FA COM CONTRAINDICAÇÃO/RISCO PROIBITIVO A ANTICOAGULANTE ORAL.'),
  ('Síncope e Anticoagulação', 'O SUCESSO DA ABLAÇÃO DE FA PERMITE SUSPENDER ANTICOAGULAÇÃO?', 'NÃO, DECISÃO SEGUE O CHA2DS2-VASC.'),
  ('Síncope e Anticoagulação', 'AAS ISOLADO OU COM CLOPIDOGREL É ALTERNATIVA SEGURA NA FA?', 'NÃO, RISCO DE AVC PERMANECE ELEVADO.');
insert into flashcards (tema, pergunta, resposta) values
  ('Hipertensão', 'QUAL O VALOR DE CORTE DA MRPA PARA DIAGNÓSTICO DE HAS?', '≥130X80MMHG (MESMO VALOR DA MÉDIA 24H DA MAPA).'),
  ('Hipertensão', 'COMO SE DEFINE O EFEITO DO AVENTAL BRANCO?', 'DIFERENÇA ≥20MMHG NA PAS E/OU ≥10MMHG NA PAD ENTRE CONSULTÓRIO E FORA DELE.'),
  ('Hipertensão', 'O QUE É HIPERTENSÃO DO AVENTAL BRANCO?', 'PA ELEVADA NO CONSULTÓRIO, NORMAL FORA DELE.'),
  ('Hipertensão', 'O QUE É HIPERTENSÃO MASCARADA?', 'PA NORMAL NO CONSULTÓRIO, ELEVADA FORA DELE — MAIOR RISCO CARDIOVASCULAR.'),
  ('Hipertensão', 'A PARTIR DE QUE IDADE MEDIR PA NA ROTINA PEDIÁTRICA?', '3 ANOS, ANUALMENTE.'),
  ('Hipertensão', 'COMO SE DEFINE HIPERTENSÃO NA CRIANÇA?', 'PA ≥ PERCENTIL 95 PARA IDADE, SEXO E ALTURA.'),
  ('Hipertensão', 'QUANDO A MRPA É ESPECIALMENTE INDICADA?', 'PA ELEVADA EM CONSULTÓRIO, BAIXO RISCO, SEM LESÃO DE ÓRGÃO-ALVO, ASSINTOMÁTICO.'),
  ('Hipertensão', 'O DESCENSO NOTURNO É AVALIADO POR MAPA OU MRPA?', 'MAPA (REGISTRO CONTÍNUO INCLUINDO O SONO).'),
  ('Hipertensão', 'COMO SE DEFINE HIPOTENSÃO ORTOSTÁTICA?', 'QUEDA DA PAS ≥20MMHG E/OU PAD ≥10MMHG ATÉ O 3º MINUTO EM ORTOSTASE.'),
  ('Hipertensão', 'EM QUAIS POPULAÇÕES PESQUISAR HIPOTENSÃO ORTOSTÁTICA?', 'IDOSOS, DIABÉTICOS, DISAUTONÔMICOS, USUÁRIOS DE ANTI-HIPERTENSIVOS.'),
  ('Hipertensão', 'DIFERENÇA DE PAS >15MMHG ENTRE OS BRAÇOS SUGERE O QUÊ?', 'MAIOR RISCO CARDIOVASCULAR/DOENÇA VASCULAR.'),
  ('Hipertensão', 'QUANDO USAR A FASE IV DE KOROTKOFF PARA A PAD?', 'DÉBITO HIPERDINÂMICO (EX.: GESTAÇÃO), SONS PERSISTEM ATÉ ZERO.'),
  ('Hipertensão', 'QUE CUIDADO TER COM EXERCÍCIO ANTES DE MEDIR A PA?', 'EVITAR NOS 30 MINUTOS ANTERIORES.'),
  ('Hipertensão', 'QUAIS SÃO MARCADORES DE LESÃO SUBCLÍNICA DE ÓRGÃO-ALVO?', 'HVE (SOKOLOW-LYON >35MM), CARÓTIDA >0,9MM, TFG <60, ITB <0,9, MICROALBUMINÚRIA 30-300MG/G.'),
  ('Hipertensão', 'QUAL A FAIXA DA MICROALBUMINÚRIA?', '30 A 300 MG/24H (OU MG/G).'),
  ('Hipertensão', 'QUAL O VALOR NORMAL DO ITB?', '0,9 A 1,3.'),
  ('Hipertensão', 'COMO INICIAR TRATAMENTO EM HAS ESTÁGIO 1 RISCO MODERADO (SBC 2020)?', 'COMBINAÇÃO INICIAL DE 2 FÁRMACOS (IECA/BRA + DIURÉTICO OU BCC).'),
  ('Hipertensão', 'QUAL COMBINAÇÃO INICIAL PREFERIR COM HVE + MICROALBUMINÚRIA?', 'INIBIDOR DO SRAA + BCC (NEFROPROTEÇÃO + REGRESSÃO DE HVE).'),
  ('Hipertensão', 'QUAL DIURÉTICO É PREFERIDO NO TRATAMENTO CRÔNICO DA HAS?', 'TIAZÍDICOS/SIMILARES EM DOSES BAIXAS.'),
  ('Hipertensão', 'CLORTALIDONA VS HIDROCLOROTIAZIDA: QUAL TEM MAIOR POTÊNCIA E MEIA-VIDA MAIOR?', 'CLORTALIDONA.'),
  ('Hipertensão', 'MECANISMO PREDOMINANTE DO EFEITO ANTI-HIPERTENSIVO DOS TIAZÍDICOS NAS PRIMEIRAS SEMANAS?', 'REDUÇÃO DO VOLUME EXTRACELULAR.'),
  ('Hipertensão', 'QUAL O MECANISMO PREDOMINANTE DO EFEITO ANTI-HIPERTENSIVO DOS TIAZÍDICOS APÓS USO PROLONGADO?', 'REDUÇÃO DA RESISTÊNCIA VASCULAR PERIFÉRICA.'),
  ('Hipertensão', 'QUAL DISTÚRBIO ELETROLÍTICO CLÁSSICO DOS TIAZÍDICOS E SUA CONSEQUÊNCIA?', 'HIPOCALEMIA, AUMENTANDO RISCO DE DM2.'),
  ('Hipertensão', 'OS TIAZÍDICOS AUMENTAM RISCO DE DISFUNÇÃO ERÉTIL?', 'SIM.'),
  ('Hipertensão', 'EFEITO ADVERSO ODONTOLÓGICO DOS BCC DI-IDROPIRIDÍNICOS?', 'HIPERPLASIA GENGIVAL (REVERSÍVEL).'),
  ('Hipertensão', 'EFEITO COLATERAL MAIS COMUM DOS BCC DI-IDROPIRIDÍNICOS?', 'EDEMA MALEOLAR.'),
  ('Hipertensão', 'O ANLODIPINO É DI-IDROPIRIDÍNICO E TEM MEIA-VIDA?', 'SIM, LONGA (35-50H), DOSE ÚNICA DIÁRIA.'),
  ('Hipertensão', 'POR QUE O DUPLO BLOQUEIO DO SRAA (IECA+BRA) É CONTRAINDICADO?', 'RISCO DE HIPERCALEMIA E PIORA RENAL, SEM BENEFÍCIO ADICIONAL.'),
  ('Hipertensão', 'ONDE ATUAM ALISQUIRENO, ENALAPRIL E LOSARTANA?', 'ALISQUIRENO: RENINA / ENALAPRIL (IECA): CONVERSÃO ANGIO I→II / LOSARTANA (BRA): RECEPTOR AT1.'),
  ('Hipertensão', 'QUANDO O PROPRANOLOL É CONTRAINDICADO?', 'ASMA EM ATIVIDADE (BLOQUEIO BETA-2 → BRONCOESPASMO).'),
  ('Hipertensão', 'INDICAÇÃO CLÁSSICA DE BETABLOQUEADOR EM HIPERTENSO COM ANGINA E FC ALTA?', 'CONTROLE DE FREQUÊNCIA/CONSUMO DE O2.'),
  ('Hipertensão', 'QUAIS BETABLOQUEADORES TÊM EVIDÊNCIA EM ICFER?', 'CARVEDILOL, BISOPROLOL, SUCCINATO DE METOPROLOL.'),
  ('Hipertensão', 'BETABLOQUEADOR HIDROFÍLICO (EX.: ATENOLOL) NO IDOSO: PENETRA MAIS OU MENOS NO SNC?', 'MENOS, MELHOR TOLERADO.'),
  ('Hipertensão', 'MECANISMO DA DOXAZOSINA?', 'ANTAGONISTA ALFA-1 (ÚTIL EM HAS + HPB).'),
  ('Hipertensão', 'MECANISMO DO MINOXIDIL?', 'ABERTURA DE CANAIS DE K+ ATP-SENSÍVEIS (VASODILATADOR POTENTE).'),
  ('Hipertensão', 'MECANISMO DA METILDOPA E CLONIDINA?', 'AGONISTAS ALFA-2 DE AÇÃO CENTRAL.'),
  ('Hipertensão', 'COMO SE DEFINE HIPERTENSÃO RESISTENTE?', 'NÃO CONTROLADA COM 3 CLASSES OTIMIZADAS, INCLUINDO DIURÉTICO.'),
  ('Hipertensão', 'COMO SE DEFINE HIPERTENSÃO REFRATÁRIA?', 'NÃO CONTROLADA APESAR DE ≥5 CLASSES OTIMIZADAS.'),
  ('Hipertensão', 'O QUE EXCLUIR ANTES DE ROTULAR COMO RESISTENTE VERDADEIRA?', 'PSEUDORRESISTÊNCIA (AVENTAL BRANCO), VIA MAPA/MRPA.'),
  ('Hipertensão', 'QUARTO FÁRMACO DE ESCOLHA NA HIPERTENSÃO RESISTENTE?', 'ESPIRONOLACTONA (ESTUDO PATHWAY-2).'),
  ('Hipertensão', 'CAUSA SECUNDÁRIA MAIS PREVALENTE DE HAS RESISTENTE?', 'SAHOS.'),
  ('Hipertensão', 'PADRÃO DE MAPA SUGESTIVO DE APNEIA DO SONO?', '"NON-DIPPER" OU "RISER" (PA NOTURNA > VIGÍLIA).'),
  ('Hipertensão', 'ACHADOS CLÍNICOS QUE AUMENTAM SUSPEITA DE SAOS?', 'OBESIDADE, CIRCUNFERÊNCIA CERVICAL AUMENTADA, SONO RUIM, SÍNDROME METABÓLICA.'),
  ('Hipertensão', 'EXAME CONFIRMATÓRIO E TRATAMENTO DA SAOS MODERADA-GRAVE?', 'POLISSONOGRAFIA; CPAP.'),
  ('Hipertensão', 'QUANDO RASTREAR HIPERALDOSTERONISMO?', 'HIPOCALEMIA, HAS RESISTENTE, OU INCIDENTALOMA ADRENAL.'),
  ('Hipertensão', 'QUAL O TESTE DE RASTREIO PARA HIPERALDOSTERONISMO E SEU PONTO DE CORTE?', 'RELAÇÃO ALDOSTERONA/RENINA; POSITIVO SE >30.'),
  ('Hipertensão', 'QUAIS DROGAS SUSPENDER ANTES DO RASTREIO DE HIPERALDOSTERONISMO (INTERFEREM NA RELAÇÃO A/R)?', 'ESPIRONOLACTONA (4-6 SEMANAS), IECA, BRA, BETABLOQUEADOR, DIURÉTICO POUPADOR DE K+.'),
  ('Hipertensão', 'QUAL ANTI-HIPERTENSIVO É SEGURO DURANTE A INVESTIGAÇÃO DE HIPERALDOSTERONISMO?', 'ANLODIPINO.'),
  ('Hipertensão', 'APÓS RASTREIO POSITIVO PARA HIPERALDOSTERONISMO, QUAL O PRÓXIMO PASSO?', 'TESTE CONFIRMATÓRIO (SOBRECARGA SALINA OU FUROSEMIDA+ORTOSTASE).'),
  ('Hipertensão', 'ACHADO TOMOGRÁFICO CLÁSSICO DE ADENOMA PRODUTOR DE ALDOSTERONA?', 'NÓDULO HIPODENSO BEM DELIMITADO (<10HU).'),
  ('Hipertensão', 'QUAL EXAME DIFERENCIA ADENOMA UNILATERAL DE HIPERPLASIA BILATERAL?', 'CATETERISMO DE VEIAS ADRENAIS (LATERALIZAÇÃO).'),
  ('Hipertensão', 'O RISCO CARDIOVASCULAR DO HIPERALDOSTERONISMO É IGUAL AO DA HAS PRIMÁRIA?', 'NÃO, MAIOR.'),
  ('Hipertensão', 'TRÍADE CLÁSSICA DO FEOCROMOCITOMA?', 'CEFALEIA + SUDORESE + PALPITAÇÕES, EM CRISES PAROXÍSTICAS.'),
  ('Hipertensão', 'RUBOR OU PALIDEZ DURANTE AS CRISES DE FEOCROMOCITOMA?', 'PALIDEZ.'),
  ('Hipertensão', 'QUAL O EXAME DE RASTREIO DE ESCOLHA PARA FEOCROMOCITOMA?', 'METANEFRINAS URINÁRIAS.'),
  ('Hipertensão', 'ACHADO CLÍNICO CLÁSSICO QUE SUGERE HAS RENOVASCULAR?', 'EDEMA AGUDO DE PULMÃO SÚBITO/RECORRENTE ("FLASH PULMONARY EDEMA").'),
  ('Hipertensão', 'PRINCIPAL CAUSA DE HAS RENOVASCULAR EM JOVENS?', 'DISPLASIA FIBROMUSCULAR.'),
  ('Hipertensão', 'ATIVIDADE DE RENINA NA HAS RENOVASCULAR?', 'AUMENTADA.'),
  ('Hipertensão', 'QUANDO IECA/BRA SÃO CONTRAINDICADOS NA HAS RENOVASCULAR?', 'ESTENOSE BILATERAL (OU UNILATERAL EM RIM ÚNICO).'),
  ('Hipertensão', 'DIFERENÇA ENTRE EMERGÊNCIA E URGÊNCIA HIPERTENSIVA?', 'EMERGÊNCIA: LESÃO AGUDA DE ÓRGÃO-ALVO, TRATAMENTO PARENTERAL. URGÊNCIA: SEM LESÃO AGUDA, ORAL GRADUAL EM 24-48H.'),
  ('Hipertensão', 'COMO DEVE SER A REDUÇÃO DA PA NA EMERGÊNCIA HIPERTENSIVA?', 'GRADUAL, ~20-25% NAS PRIMEIRAS 1-2H, NUNCA ABRUPTA.'),
  ('Hipertensão', 'DROGA DE ESCOLHA NA EMERGÊNCIA HIPERTENSIVA COM IC AGUDA?', 'NITROPRUSSIATO DE SÓDIO.'),
  ('Hipertensão', 'POR QUE EVITAR LABETALOL EM BRONCOESPÁSTICO?', 'COMPONENTE BETABLOQUEADOR PODE PRECIPITAR BRONCOESPASMO.'),
  ('Hipertensão', 'O QUE DEFINE A HAS MALIGNA?', 'PA GRAVEMENTE ELEVADA + RETINOPATIA GRAVE, PACIENTE LÚCIDO.'),
  ('Hipertensão', 'O QUE DIFERENCIA A ENCEFALOPATIA HIPERTENSIVA DA HAS MALIGNA?', 'ALTERAÇÃO DO ESTADO MENTAL NA ENCEFALOPATIA.'),
  ('Hipertensão', 'O TRATAMENTO DA HAS NO IDOSO SEGUE META RÍGIDA IGUAL PARA TODOS?', 'NÃO, INDIVIDUALIZADO CONFORME FRAGILIDADE E FUNCIONALIDADE.'),
  ('Hipertensão', 'O ENVELHECIMENTO VASCULAR AUMENTA OU REDUZ A COMPLACÊNCIA ARTERIAL?', 'REDUZ.'),
  ('Hipertensão', 'QUAL MEDIDA TEM MAIOR IMPACTO NA PA EM OBESIDADE IMPORTANTE?', 'PERDA DE PESO (~1MMHG DE PAS POR KG).'),
  ('Hipertensão', 'QUAL A RECOMENDAÇÃO DE SÓDIO PARA PREVENÇÃO PRIMÁRIA DE HAS?', 'ATÉ 2G/DIA (~5G DE SAL).'),
  ('Hipertensão', 'SUPLEMENTAÇÃO DE POTÁSSIO EM COMPRIMIDOS É RECOMENDADA?', 'NÃO, PREFERIR DIETA.'),
  ('Hipertensão', 'O ÁLCOOL DEVE SER ESTIMULADO COMO PREVENÇÃO DE HAS?', 'NÃO, EXCESSO É FATOR DE RISCO.'),
  ('Hipertensão', 'A DENERVAÇÃO SIMPÁTICA RENAL TEM INDICAÇÃO CONSOLIDADA HOJE?', 'NÃO, ESTUDOS SHAM-CONTROLADOS QUESTIONARAM O BENEFÍCIO.');
insert into flashcards (tema, pergunta, resposta) values
  ('Coronária Crônica', 'QUAL A EXTRAÇÃO BASAL DE O2 PELO MIOCÁRDIO EM REPOUSO?', 'JÁ MUITO ALTA (60-80%), PRÓXIMA DO MÁXIMO.'),
  ('Coronária Crônica', 'PRINCIPAL MECANISMO COMPENSATÓRIO QUANDO AUMENTA A DEMANDA DE O2?', 'AUMENTO DO FLUXO CORONARIANO (VASODILATAÇÃO), NÃO DA EXTRAÇÃO.'),
  ('Coronária Crônica', 'DETERMINANTES DO CONSUMO MIOCÁRDICO DE O2 (MVO2)?', 'FREQUÊNCIA CARDÍACA, TENSÃO DE PAREDE, CONTRATILIDADE.'),
  ('Coronária Crônica', 'CARACTERÍSTICAS DA ANGINA TÍPICA?', 'INÍCIO GRADUAL, DIFUSA, 2-5 MIN, SEM RELAÇÃO COM POSIÇÃO/RESPIRAÇÃO, MELHORA COM REPOUSO.'),
  ('Coronária Crônica', 'SINAL CLÁSSICO DE DOR ISQUÊMICA AO EXAME?', 'SINAL DE LEVINE (PUNHO CERRADO SOBRE O ESTERNO).'),
