  ('Dislipidemia', 'HÁ BENEFÍCIO NO TRATAMENTO DE DISLIPIDEMIA EM DIALÍTICO?', 'NÃO, ESTUDO AURORA (SE JÁ USAVA, PODE MANTER)'),
  ('Dislipidemia', 'QUAIS OS CRITÉRIOS PARA SÍNDROME METABÓLICA?', 'CIRCUNFERÊNCIA ABDOMINAL AUMENTADA E DOIS DOS SEGUINTES: HDL <40 (H) E <50 (M) TRIGLICÉRIDES >150 GLICEMIA JEJUM >100 PA >130X85 ATENÇÃO: LDL NÃO É CRITÉRIO!'),
  ('Dislipidemia', 'QUAL O PRINCIPAL TRATAMENTO DA HIPERTRIGLICIRIDEMIA?', 'MUDANÇA DO ESTILO DE VIDA E CESSAR ALCOOLISMO OBS: O USO DE FIBRATO QUANDO >500 É PARA EVITAR PANCREATITE, NÃO REDUZ DESFECHOS CARDIOVASCULARES'),
  ('Dislipidemia', 'QUAL A AÇÃO DAS ESTATINAS?', 'INIBIÇÃO DA HMG-CoA redutase HEPÁTICA, AUMENTA RECEPTOR DE LDL, REDUZINDO LDL SÉRICO'),
  ('Dislipidemia', 'QUAL A AÇÃO DA EZETIMIBA?', 'INIBIR A NPC1L1 INTESTINAL, REDUZINDO LDL'),
  ('Dislipidemia', 'QUAL A AÇÃO DO EVOCULUMABE E DA INCLISIRANA?', 'EVOCULUMABE: ANTICORPO MONOCLONAL QUE INIBE PCSK9, REDUZ LDL INCLISIRANA: INIBIDOR DA TRANSCRIÇÃO DO RNA DA PCSK9, REDUZ LDL OBS: SÃO DROGAS DE 3 ESCOLHA (APÓS USO DE ESTATINA DOSE MÁXIMA COM EZETIMIBA)'),
  ('Dislipidemia', 'QUAL A AÇÃO DAS RESINAS INTESTINAIS (COLESTIRAMINA)?', 'BLOQUEAR REABSORÇÃO DE ACIDOS BILIARES (REDUZ ABSORÇÃO DE VITAMINAS LIPOSSOLÚVEIS) OBS: PODE SER USADO EM GESTANTES E LACTANTES!'),
  ('Dislipidemia', 'QUAL A AÇÃO DOS FIBRATOS?', 'ATIVAÇÃO DA PPAR-ALFA COM AUMENTO DA LIPASE LIPOPROTEICA HEPÁTICA (REDUZ TRIGLICÉRIDES)'),
  ('Dislipidemia', 'QUAL A AÇÃO DO OMEGA 3?', 'REDUÇÃO DE TRIGLICERIDES E VLDL OBS: TEM BENEFÍCIO CARDIOVASCULAR O USO DA MOLÉCULA "EPA", EM PACIENTES ALTO RISCO, JA EM USO DE ESTATINA ALTA POTÊNCIA E COM TRIGLICÉRIDES ELEVADO'),
  ('Dislipidemia', 'QUAL A AÇÃO DO ÁCIDO NICOTÍNICO?', 'REDUÇÃO DA LIPASE TECIDUAL OBS: PODE CAUSAR "FLUSHING" FACIAL!'),
  ('Dislipidemia', 'QUANDO PENSAR EM HIPERCOLESTEROLEMIA FAMILIAR (HF)?', 'LDL 2-3X VR (HETEROZIGÓTICO) OU 6-7X VR (HOMOZIGÓTICO), COM XANTOMAS TENDINOSOS, XANTELASMA <25A OU ARCO CÓRNEO <45A E (OU) HISTÓRIA FAMILIAR DAC PRECOCE OBS: ANTES DESCARTAR SÍNDROME NEFRÓTICA E HIPOTIREOIDISMO'),
  ('Dislipidemia', 'DEVO FAZER O RASTREAMENTO EM "CASCATA" DE FAMILIARES COM HF?', 'SIM, PERMITE DIAGNÓSTICOS PRECOCES'),
  ('Dislipidemia', 'QUANDO PENSAR EM QUILOMICRONEMIA FAMILIAR (SQF)?', 'TRIGLICERIDES >1500, XANTOMAS ERUPTIVOS, PANCREATITE, LIPEMIA RETINALIS. É UMA SÍNDROME RARA, AUTOSSÔMICA RECESSIVA'),
  ('Dislipidemia', 'QUAL O TRATAMENTO DA QUILOMICRONEMIA FAMILIAR (SQF)?', 'RESPONDE POUCO AO TRATAMENTO PADRÃO TRATAMENTO ESPECÍFICO: VOLANESORSEN (INIBE APOC3)'),
  ('Dislipidemia', 'O ESCORE DE CÁLCIO É INDICADO EM PACIENTES SINTOMÁTICOS COM DOR TORÁCICA?', 'NÃO, É FERRAMENTA DE PREVENÇÃO PRIMÁRIA EM ASSINTOMÁTICOS; DOR TORÁCICA SEGUE INVESTIGAÇÃO DE ISQUEMIA'),
  ('Dislipidemia', 'O ESCORE DE CÁLCIO AGREGA VALOR EM PACIENTE JÁ CLASSIFICADO COMO ALTO RISCO PELO FRAMINGHAM?', 'NÃO, POIS JÁ TEM INDICAÇÃO DE ESTATINA INDEPENDENTE DO RESULTADO'),
  ('Dislipidemia', 'O ESCORE DE CÁLCIO TEM PAPEL NA INVESTIGAÇÃO DE ANGINA INSTÁVEL/SCA?', 'NÃO, É FERRAMENTA DE PREVENÇÃO CRÔNICA, NÃO DE QUADRO AGUDO'),
  ('Dislipidemia', 'UM ESCORE DE CÁLCIO ZERO EXCLUI ESTENOSE CORONARIANA SIGNIFICATIVA EM PACIENTE SINTOMÁTICO?', 'NÃO, PLACA JOVEM RICA EM LIPÍDIOS AINDA NÃO CALCIFICADA PODE CAUSAR ESTENOSE MESMO COM CAC=0'),
  ('Dislipidemia', 'QUAL A CONDUTA COM ESCORE DE CÁLCIO (CAC) ENTRE 1-99 AGATSTON E/OU PERCENTIL ≥75?', 'CONSIDERAR ESTATINA, PRINCIPALMENTE SE IDADE >55 ANOS'),
  ('Dislipidemia', 'A DEMONSTRAÇÃO DE ATEROSCLEROSE SUBCLÍNICA (CAC>100, PLACA EM CARÓTIDA, ITB<0,9, PLACA EM ANGIOTC) JÁ CLASSIFICA COMO ALTO RISCO POR SI SÓ?', 'SIM, INDEPENDENTE DO ESCORE CLÍNICO'),
  ('Dislipidemia', 'QUAL A BASE MOLECULAR DOS EFEITOS PLEIOTRÓPICOS DAS ESTATINAS?', 'BLOQUEIO DA VIA DO MEVALONATO TAMBÉM REDUZ A PRENILAÇÃO DE PEQUENAS GTPASES (RHO, RAS), ENVOLVIDAS EM SINALIZAÇÃO INFLAMATÓRIA E PRÓ-TROMBÓTICA'),
  ('Dislipidemia', 'AS ESTATINAS REDUZEM MORTALIDADE TOTAL (NÃO SÓ DESFECHOS CV)?', 'SIM, INCLUSIVE EM PREVENÇÃO PRIMÁRIA'),
  ('Dislipidemia', 'AS ESTATINAS REDUZEM TROMBOEMBOLISMO VENOSO?', 'SIM (ESTUDO JUPITER), ALÉM DO ARTERIAL'),
  ('Dislipidemia', 'EXISTE RELAÇÃO DOSE-RESPOSTA ENTRE REDUÇÃO DE LDL E BENEFÍCIO CLÍNICO COM O USO DE ESTATINAS?', 'SIM, QUANTO MAIOR A REDUÇÃO DE LDL, MAIOR A REDUÇÃO DE EVENTOS'),
  ('Dislipidemia', 'QUAL A POSOLOGIA DA EZETIMIBA?', '10MG, 1X AO DIA'),
  ('Dislipidemia', 'A ASSOCIAÇÃO EZETIMIBA+ESTATINA TEM BENEFÍCIO EM ESTENOSE AÓRTICA (ESTUDO SEAS)?', 'REDUZ EVENTOS CARDIOVASCULARES, MAS SEM IMPACTO NA PROGRESSÃO DA PRÓPRIA ESTENOSE VALVAR'),
  ('Dislipidemia', 'A EZETIMIBA PIORA A ESTEATOSE HEPÁTICA NÃO ALCOÓLICA?', 'NÃO, PODE ATÉ TRAZER BENEFÍCIO'),
  ('Dislipidemia', 'QUAL O MECANISMO DO ÔMEGA-3 NA REDUÇÃO DE TRIGLICÉRIDES?', 'REDUZ A SÍNTESE HEPÁTICA DE VLDL (E, CONSEQUENTEMENTE, DE APOB CARREADA POR ELA)'),
  ('Dislipidemia', 'O CONSUMO DE ÁLCOOL (INCLUSIVE VINHO TINTO) DEVE SER RECOMENDADO COMO MEDIDA TERAPÊUTICA NA DISLIPIDEMIA?', 'NÃO, ESPECIALMENTE NA HIPERTRIGLICERIDEMIA, QUE O ÁLCOOL PIORA');

