  ('Ausculta', 'QUAIS ACHADOS AUSCULTATÓRIOS PODEM SURGIR DURANTE UM EPISÓDIO ANGINOSO AGUDO?', 'B3 (DISFUNÇÃO SISTÓLICA TRANSITÓRIA), B4 (REDUÇÃO AGUDA DA COMPLACÊNCIA), SOPRO DE IM TRANSITÓRIO (DISFUNÇÃO DE MÚSCULO PAPILAR) E DESDOBRAMENTO PARADOXAL DE B2 (ATRASO NA EJEÇÃO DO VE ISQUÊMICO)'),
  ('Ausculta', 'UM SOPRO MESOSSISTÓLICO SUAVE (ATÉ 2+/6+), ISOLADO E ASSINTOMÁTICO PRECISA DE ECOCARDIOGRAMA DE ROTINA?', 'NÃO, GERALMENTE FUNCIONAL/INOCENTE'),
  ('Ausculta', 'SOPROS HOLOSSISTÓLICO, PROTOSSISTÓLICO, TELESSISTÓLICO OU PRÉ-SISTÓLICO SEMPRE MERECEM INVESTIGAÇÃO COM ECOCARDIOGRAMA?', 'SIM, SÃO SEMPRE PATOLÓGICOS/MERECEM AVALIAÇÃO'),
  ('Ausculta', 'ONDE É MELHOR AUSCULTADO O SOPRO DE INSUFICIÊNCIA AÓRTICA POR DOENÇA VALVAR PRIMÁRIA (EX.: BICÚSPIDE)?', '3º/4º EIC DE BORDA ESTERNAL ESQUERDA (FOCO AÓRTICO ACESSÓRIO)'),
  ('Ausculta', 'ONDE É MELHOR AUSCULTADO O SOPRO DE INSUFICIÊNCIA AÓRTICA POR DILATAÇÃO DA RAIZ AÓRTICA (ANEURISMA, MARFAN, DISSECÇÃO)?', 'BORDA ESTERNAL DIREITA ALTA (JATO SE DIRECIONA MAIS PARA A DIREITA)'),
  ('Ausculta', 'O QUE O HANDGRIP FAZ COM O SOPRO DA INSUFICIÊNCIA AÓRTICA E DA INSUFICIÊNCIA MITRAL?', 'AUMENTA (AUMENTA PÓS-CARGA, FAVORECE REGURGITAÇÃO)'),
  ('Ausculta', 'QUAIS SINAIS INDICAM INSUFICIÊNCIA AÓRTICA IMPORTANTE/GRAVE?', 'SOPRO HOLODIASTÓLICO ASPIRATIVO COM B2 HIPOFONÉTICA, AUSTIN-FLINT, PULSO EM MARTELO D''ÁGUA, SOPRO MESOSSISTÓLICO DE HIPERFLUXO MAIS INTENSO'),
  ('Ausculta', 'A PIORA DO SOPRO COM HANDGRIP É MARCADOR ESPECÍFICO DE GRAVIDADE DA INSUFICIÊNCIA AÓRTICA?', 'NÃO, É INESPECÍFICO (OCORRE EM QUALQUER SOPRO DE REGURGITAÇÃO)'),
